//! `cargo xtask generate-runtime-client`: writes the generated files of the TypeScript client
//! package `@tatolab/runtime-client` from the committed control contract file. `--check` is the
//! CI gate that fails when a checked-in generated file differs from a regeneration.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::Path;

use crate::runtime_client_zod_schemas::{ZodSchemasOfOneContractEntry, zod_schemas_javascript};
use anyhow::{Context, Result, bail};
use serde_json::{Map, Value};
use streamlib_control_contract::{
    CONTROL_CONTRACT_FILE_WORKSPACE_PATH, CONTROL_CONTRACT_VERSION_MISMATCH_ERROR_CODE,
    CONTROL_OPERATION_FAILED_ERROR_CODE, CONTROL_OPERATION_REFUSED_ERROR_CODE,
};

use streamlib_runtime_client_contract::local_api_wire_contract::{
    CONTROL_CLIENT_NAME_HEADER_NAME, CONTROL_CONTRACT_VERSION_HEADER_NAME,
    CONTROL_JSON_RPC_ROUTE_PATH, CONTROL_JSON_RPC_WEBSOCKET_REQUEST_TARGET,
};

/// The client package's directory, relative to the workspace.
pub const RUNTIME_CLIENT_PACKAGE_RELATIVE_TO_WORKSPACE: &str = "sdk/tatolab-runtime-client";

/// The files of the client package the runtime unit carries, relative to the package; the
/// type-check and integration fixtures stay in the tree.
pub const RUNTIME_CLIENT_PACKAGE_FILES_THE_RUNTIME_UNIT_CARRIES: &[&str] = &[
    "package.json",
    "index.js",
    "index.d.ts",
    "runtime_client.js",
    "runtime_client.d.ts",
    "control_messages.js",
    "control_messages.d.ts",
    "control_transports.js",
    "control_transports.d.ts",
    GENERATED_CONTRACT_TYPES_FILE_NAME,
    GENERATED_CONTRACT_CONSTANTS_FILE_NAME,
    GENERATED_SCHEMAS_FILE_NAME,
    GENERATED_SCHEMAS_TYPES_FILE_NAME,
    GENERATED_CLIENT_FILE_NAME,
    GENERATED_CLIENT_TYPES_FILE_NAME,
    GENERATED_REFERENCE_FILE_NAME,
    COPIED_CONTRACT_FILE_NAME,
];

const GENERATED_CONTRACT_TYPES_FILE_NAME: &str = "control_contract.d.ts";
const GENERATED_CONTRACT_CONSTANTS_FILE_NAME: &str = "control_contract.js";
const GENERATED_SCHEMAS_FILE_NAME: &str = "control_schemas.js";
const GENERATED_SCHEMAS_TYPES_FILE_NAME: &str = "control_schemas.d.ts";
const GENERATED_CLIENT_FILE_NAME: &str = "control_client.js";
const GENERATED_CLIENT_TYPES_FILE_NAME: &str = "control_client.d.ts";
const GENERATED_REFERENCE_FILE_NAME: &str = "REFERENCE.md";
const COPIED_CONTRACT_FILE_NAME: &str = "contract.json";

/// Each error code the contract declares, by the name its Rust constant has.
const CONTROL_ERROR_CODE_CONSTANT_NAMES: &[(i64, &str)] = &[
    (
        CONTROL_OPERATION_REFUSED_ERROR_CODE,
        "CONTROL_OPERATION_REFUSED_ERROR_CODE",
    ),
    (
        CONTROL_OPERATION_FAILED_ERROR_CODE,
        "CONTROL_OPERATION_FAILED_ERROR_CODE",
    ),
    (
        CONTROL_CONTRACT_VERSION_MISMATCH_ERROR_CODE,
        "CONTROL_CONTRACT_VERSION_MISMATCH_ERROR_CODE",
    ),
];

/// The local API routes and headers a client of the control API sends, by constant name.
const CONTROL_LOCAL_API_WIRE_CONSTANTS: &[(&str, &str, &str)] = &[
    (
        "CONTROL_JSON_RPC_ROUTE_PATH",
        CONTROL_JSON_RPC_ROUTE_PATH,
        "The route one JSON-RPC request is POSTed to.",
    ),
    (
        "CONTROL_JSON_RPC_WEBSOCKET_REQUEST_TARGET",
        CONTROL_JSON_RPC_WEBSOCKET_REQUEST_TARGET,
        "The route a WebSocket is opened at to carry one JSON-RPC message per text frame both ways.",
    ),
    (
        "CONTROL_CONTRACT_VERSION_HEADER_NAME",
        CONTROL_CONTRACT_VERSION_HEADER_NAME,
        "The header naming the contract version a client was built against.",
    ),
    (
        "CONTROL_CLIENT_NAME_HEADER_NAME",
        CONTROL_CLIENT_NAME_HEADER_NAME,
        "The header naming the client, the author of a change it sends with no author.",
    ),
];

/// The members of `TatolabRuntimeClientCallsOverATransport` a generated method would hide.
const CLIENT_MEMBER_NAMES_NO_METHOD_MAY_TAKE: &[&str] = &[
    "call",
    "close",
    "closed",
    "constructor",
    "discovered",
    "onNotification",
    "onNotificationInvalid",
];

/// What a notification's listener method is named with before the notification's name.
const NOTIFICATION_LISTENER_METHOD_PREFIX: &str = "on_";

pub(crate) const COMPONENT_SCHEMA_REFERENCE_PREFIX: &str = "#/components/schemas/";

pub(crate) const GENERATED_SOURCE_HEADER: &str = "// Copyright (c) 2025 Jonathan Fontanez\n\
// SPDX-License-Identifier: BUSL-1.1\n\
//\n\
// Generated by `cargo xtask generate-runtime-client` from contract.json; do not edit.\n";

/// Regenerate the client package's generated files, or with `check_only` fail when a
/// checked-in one differs from a regeneration.
pub fn run(workspace_root: &Path, check_only: bool) -> Result<()> {
    let contract_file_path = workspace_root.join(CONTROL_CONTRACT_FILE_WORKSPACE_PATH);
    let contract_file_contents = std::fs::read_to_string(&contract_file_path)
        .with_context(|| format!("reading {}", contract_file_path.display()))?;
    let contract: Value = serde_json::from_str(&contract_file_contents)
        .with_context(|| format!("parsing {}", contract_file_path.display()))?;
    let generated_files = runtime_client_generated_files(&contract, &contract_file_contents)?;
    let package_directory = workspace_root.join(RUNTIME_CLIENT_PACKAGE_RELATIVE_TO_WORKSPACE);
    if check_only {
        let mut differing_files = Vec::new();
        for (file_name, generated_contents) in &generated_files {
            let checked_in_contents =
                std::fs::read_to_string(package_directory.join(file_name)).unwrap_or_default();
            if &checked_in_contents != generated_contents {
                differing_files.push(*file_name);
            }
        }
        if !differing_files.is_empty() {
            bail!(
                "{RUNTIME_CLIENT_PACKAGE_RELATIVE_TO_WORKSPACE} differs from what \
                 {CONTROL_CONTRACT_FILE_WORKSPACE_PATH} generates in {}: run `cargo xtask \
                 generate-runtime-client` and commit the result.",
                differing_files.join(", ")
            );
        }
        tracing::info!(
            "{RUNTIME_CLIENT_PACKAGE_RELATIVE_TO_WORKSPACE} matches {CONTROL_CONTRACT_FILE_WORKSPACE_PATH}"
        );
        return Ok(());
    }
    for (file_name, generated_contents) in &generated_files {
        let file_path = package_directory.join(file_name);
        std::fs::write(&file_path, generated_contents)
            .with_context(|| format!("writing {}", file_path.display()))?;
    }
    tracing::info!(
        "wrote the generated files of {RUNTIME_CLIENT_PACKAGE_RELATIVE_TO_WORKSPACE} from \
         {CONTROL_CONTRACT_FILE_WORKSPACE_PATH}"
    );
    Ok(())
}

/// Every generated file of the package by file name, from `contract`, whose file reads
/// `contract_file_contents`.
pub fn runtime_client_generated_files(
    contract: &Value,
    contract_file_contents: &str,
) -> Result<Vec<(&'static str, String)>> {
    let control_contract = ControlContractRead::of(contract)?;
    Ok(vec![
        (
            GENERATED_CONTRACT_TYPES_FILE_NAME,
            control_contract.typescript_declarations(),
        ),
        (
            GENERATED_CONTRACT_CONSTANTS_FILE_NAME,
            control_contract.javascript_constants(),
        ),
        (
            GENERATED_SCHEMAS_FILE_NAME,
            control_contract.zod_schemas_javascript(),
        ),
        (
            GENERATED_SCHEMAS_TYPES_FILE_NAME,
            control_contract.zod_schemas_declarations(),
        ),
        (
            GENERATED_CLIENT_FILE_NAME,
            control_contract.client_javascript(),
        ),
        (
            GENERATED_CLIENT_TYPES_FILE_NAME,
            control_contract.client_declarations(),
        ),
        (
            GENERATED_REFERENCE_FILE_NAME,
            control_contract.reference_markdown(),
        ),
        (COPIED_CONTRACT_FILE_NAME, contract_file_contents.to_owned()),
    ])
}

/// One method or notification of the contract file, as the generator reads it.
struct ControlContractEntryRead<'contract> {
    name: &'contract str,
    summary: &'contract str,
    description: &'contract str,
    params_schema: &'contract Value,
    result_schema: Option<&'contract Value>,
    errors: Vec<(i64, &'contract str)>,
    since_contract_version: u64,
    stability: &'contract str,
    group: &'contract str,
    subscribed_by: &'contract str,
}

/// The parts of the contract file the generator writes from.
struct ControlContractRead<'contract> {
    contract_version: u64,
    methods: Vec<ControlContractEntryRead<'contract>>,
    notifications: Vec<ControlContractEntryRead<'contract>>,
    component_schemas: &'contract Map<String, Value>,
}

impl<'contract> ControlContractRead<'contract> {
    fn of(contract: &'contract Value) -> Result<Self> {
        let contract_version = contract["info"]["x-contract-version"]
            .as_u64()
            .context("the contract file names no `info.x-contract-version`")?;
        let component_schemas = contract["components"]["schemas"]
            .as_object()
            .context("the contract file has no `components.schemas`")?;
        let entries_of = |key: &str| -> Result<Vec<ControlContractEntryRead<'contract>>> {
            contract[key]
                .as_array()
                .with_context(|| format!("the contract file has no `{key}` array"))?
                .iter()
                .map(ControlContractEntryRead::of)
                .collect()
        };
        let methods = entries_of("methods")?;
        for method in &methods {
            for (code, message) in &method.errors {
                if !CONTROL_ERROR_CODE_CONSTANT_NAMES
                    .iter()
                    .any(|(known, _)| known == code)
                {
                    bail!(
                        "`{}` declares error code {code} ({message}), which the generator has no \
                         constant for",
                        method.name
                    );
                }
            }
        }
        for method in &methods {
            if CLIENT_MEMBER_NAMES_NO_METHOD_MAY_TAKE.contains(&method.name)
                || method.name.starts_with(NOTIFICATION_LISTENER_METHOD_PREFIX)
            {
                bail!(
                    "`{}` is the name of a member the generated client already has, so it \
                     cannot be one of its methods",
                    method.name
                );
            }
        }
        Ok(Self {
            contract_version,
            methods,
            notifications: entries_of("x-notifications")?,
            component_schemas,
        })
    }

    fn typescript_declarations(&self) -> String {
        let mut declarations = String::from(GENERATED_SOURCE_HEADER);
        declarations.push('\n');
        for (name, schema) in self.component_schemas {
            write_doc_comment(&mut declarations, "", &[description_of(schema)]);
            if is_an_object_with_properties(schema) {
                let _ = writeln!(
                    declarations,
                    "export interface {name} {}\n",
                    object_type_of(schema, 0)
                );
            } else {
                let _ = writeln!(
                    declarations,
                    "export type {name} = {};\n",
                    typescript_type_of(schema, 0)
                );
            }
        }
        declarations.push_str(
            "/** Every operation the runtime serves, by method name: the params it takes and the result it answers. */\n\
             export interface ControlOperations {\n",
        );
        for method in &self.methods {
            write_doc_comment(&mut declarations, "  ", &method.doc_paragraphs());
            let _ = writeln!(
                declarations,
                "  {}: {{\n    params: {};\n    result: {};\n  }};",
                property_key(method.name),
                typescript_type_of(method.params_schema, 2),
                method.result_schema.map_or_else(
                    || "unknown".to_owned(),
                    |schema| typescript_type_of(schema, 2)
                ),
            );
        }
        declarations.push_str("}\n\n");
        declarations.push_str(
            "/** Every notification the runtime sends a subscribed connection, by method name: the params it carries. */\n\
             export interface ControlNotifications {\n",
        );
        for notification in &self.notifications {
            write_doc_comment(&mut declarations, "  ", &notification.doc_paragraphs());
            let _ = writeln!(
                declarations,
                "  {}: {};",
                property_key(notification.name),
                typescript_type_of(notification.params_schema, 1),
            );
        }
        declarations.push_str("}\n\n");
        declarations.push_str(
            "/** A method name the runtime serves. */\n\
             export type ControlOperationMethodName = keyof ControlOperations;\n\n\
             /** A notification method name the runtime sends. */\n\
             export type ControlNotificationMethodName = keyof ControlNotifications;\n\n",
        );
        let _ = writeln!(
            declarations,
            "/** The contract version this package was generated from. */\n\
             export declare const CONTROL_CONTRACT_VERSION: {};\n\n\
             /** Every method name the contract declares, in its order. */\n\
             export declare const CONTROL_OPERATION_METHOD_NAMES: readonly ControlOperationMethodName[];\n",
            self.contract_version
        );
        for (constant_name, value, one_line_doc) in CONTROL_LOCAL_API_WIRE_CONSTANTS {
            let _ = writeln!(
                declarations,
                "/** {one_line_doc} */\nexport declare const {constant_name}: {};\n",
                json_string_literal(value)
            );
        }
        for (constant_name, code) in self.error_code_constants() {
            let _ = writeln!(
                declarations,
                "/** A JSON-RPC error code the contract declares. */\n\
                 export declare const {constant_name}: {code};\n"
            );
        }
        declarations
    }

    fn javascript_constants(&self) -> String {
        let mut constants = String::from(GENERATED_SOURCE_HEADER);
        let _ = writeln!(
            constants,
            "\nexport const CONTROL_CONTRACT_VERSION = {};\n",
            self.contract_version
        );
        constants.push_str("export const CONTROL_OPERATION_METHOD_NAMES = Object.freeze([\n");
        for method in &self.methods {
            let _ = writeln!(constants, "  {},", json_string_literal(method.name));
        }
        constants.push_str("]);\n");
        for (constant_name, value, _) in CONTROL_LOCAL_API_WIRE_CONSTANTS {
            let _ = writeln!(
                constants,
                "\nexport const {constant_name} = {};",
                json_string_literal(value)
            );
        }
        for (constant_name, code) in self.error_code_constants() {
            let _ = writeln!(constants, "\nexport const {constant_name} = {code};");
        }
        constants
    }

    /// Each distinct error code the methods declare, by its constant's name.
    fn error_code_constants(&self) -> BTreeMap<&'static str, i64> {
        CONTROL_ERROR_CODE_CONSTANT_NAMES
            .iter()
            .filter(|(code, _)| {
                self.methods
                    .iter()
                    .any(|method| method.errors.iter().any(|(declared, _)| declared == code))
            })
            .map(|(code, constant_name)| (*constant_name, *code))
            .collect()
    }

    fn zod_schemas_javascript(&self) -> String {
        let entries_of = |entries: &[ControlContractEntryRead<'contract>]| -> Vec<ZodSchemasOfOneContractEntry<'contract>> {
            entries
                .iter()
                .map(|entry| ZodSchemasOfOneContractEntry {
                    name: entry.name,
                    params_schema: entry.params_schema,
                    result_schema: entry.result_schema,
                })
                .collect()
        };
        zod_schemas_javascript(
            self.component_schemas,
            &entries_of(&self.methods),
            &entries_of(&self.notifications),
        )
    }

    fn zod_schemas_declarations(&self) -> String {
        let mut declarations = String::from(GENERATED_SOURCE_HEADER);
        declarations.push_str(
            "\nimport type { z } from \"zod\";\n\n\
             import type * as ControlContract from \"./control_contract.js\";\n\n\
             /** Every zod schema of the contract: by component, by method's params and result, and by notification's params. */\n\
             export interface ControlSchemasOfTheContract {\n  readonly components: {\n",
        );
        for name in self.component_schemas.keys() {
            let _ = writeln!(
                declarations,
                "    readonly {name}: z.ZodType<ControlContract.{name}>;"
            );
        }
        declarations.push_str(
            "  };\n  readonly operations: {\n    readonly [Method in ControlContract.ControlOperationMethodName]: {\n      readonly params: z.ZodType<ControlContract.ControlOperations[Method][\"params\"]>;\n      readonly result: z.ZodType<ControlContract.ControlOperations[Method][\"result\"]>;\n    };\n  };\n  readonly notifications: {\n    readonly [Method in ControlContract.ControlNotificationMethodName]: z.ZodType<ControlContract.ControlNotifications[Method]>;\n  };\n}\n\n\
             /** Every zod schema of the contract, which the client checks each request, answer and notification against. */\n\
             export declare const ControlSchemas: ControlSchemasOfTheContract;\n",
        );
        declarations
    }

    fn client_javascript(&self) -> String {
        let mut client = String::from(GENERATED_SOURCE_HEADER);
        client.push_str(
            "\nimport { TatolabRuntimeClientCallsOverATransport } from \"./runtime_client.js\";\n\n\
             export class TatolabRuntimeClient extends TatolabRuntimeClientCallsOverATransport {\n",
        );
        for method in &self.methods {
            let params_default = if self.takes_params_with_nothing_required(method) {
                " = {}"
            } else {
                ""
            };
            let _ = writeln!(
                client,
                "  {name}(params{params_default}, callOptions) {{\n    return this.call({method_literal}, params, callOptions);\n  }}\n",
                name = method.name,
                method_literal = json_string_literal(method.name),
            );
        }
        for notification in &self.notifications {
            let _ = writeln!(
                client,
                "  {NOTIFICATION_LISTENER_METHOD_PREFIX}{name}(listener) {{\n    return this.onNotification({method_literal}, listener);\n  }}\n",
                name = notification.name,
                method_literal = json_string_literal(notification.name),
            );
        }
        let client_without_the_last_blank_line = client.trim_end().to_owned();
        format!("{client_without_the_last_blank_line}\n}}\n")
    }

    fn client_declarations(&self) -> String {
        let mut declarations = String::from(GENERATED_SOURCE_HEADER);
        declarations.push_str(
            "\nimport type { ControlNotifications, ControlOperations } from \"./control_contract.js\";\n\
             import type {\n  ControlCallOptions,\n  TatolabRuntimeClientCallsOverATransport,\n  TatolabRuntimeClientConnectOptions,\n  TatolabRuntimeClientDiscovered,\n} from \"./runtime_client.js\";\n\n\
             /** A client of the runtime's control API: one method per operation, each request, answer and notification checked against the contract. */\n\
             export declare class TatolabRuntimeClient extends TatolabRuntimeClientCallsOverATransport {\n\
             \x20 /** Open a connection on the runtime's local API socket and `discover` over it; refused when the runtime serves another contract version. */\n\
             \x20 static connect(connectOptions: TatolabRuntimeClientConnectOptions): Promise<TatolabRuntimeClient & TatolabRuntimeClientDiscovered>;\n",
        );
        for method in &self.methods {
            let optional_marker = if self.takes_params_with_nothing_required(method) {
                "?"
            } else {
                ""
            };
            write_doc_comment(&mut declarations, "  ", &[method.summary.to_owned()]);
            let _ = writeln!(
                declarations,
                "  {name}(params{optional_marker}: ControlOperations[{method_literal}][\"params\"], callOptions?: ControlCallOptions): Promise<ControlOperations[{method_literal}][\"result\"]>;",
                name = method.name,
                method_literal = json_string_literal(method.name),
            );
        }
        for notification in &self.notifications {
            write_doc_comment(
                &mut declarations,
                "  ",
                &[format!(
                    "Hear each `{}` the connection is sent, checked against the contract; the returned function stops it. {}",
                    notification.name, notification.summary
                )],
            );
            let _ = writeln!(
                declarations,
                "  {NOTIFICATION_LISTENER_METHOD_PREFIX}{name}(listener: (params: ControlNotifications[{method_literal}]) => void): () => void;",
                name = notification.name,
                method_literal = json_string_literal(notification.name),
            );
        }
        declarations.push_str("}\n");
        declarations
    }

    /// Whether `method` takes params an empty object satisfies, so its params can be left out.
    fn takes_params_with_nothing_required(&self, method: &ControlContractEntryRead<'_>) -> bool {
        let params_schema = method.params_schema["$ref"]
            .as_str()
            .and_then(|reference| reference.strip_prefix(COMPONENT_SCHEMA_REFERENCE_PREFIX))
            .and_then(|name| self.component_schemas.get(name))
            .unwrap_or(method.params_schema);
        let is_an_object =
            params_schema.get("properties").is_some() || params_schema["type"] == "object";
        is_an_object
            && params_schema["required"]
                .as_array()
                .is_none_or(Vec::is_empty)
    }

    fn reference_markdown(&self) -> String {
        let mut reference = format!(
            "# Tatolab runtime control API\n\n\
             Generated by `cargo xtask generate-runtime-client` from `contract.json`, contract \
             version {}. Every method is a JSON-RPC 2.0 method on the runtime's local API socket: \
             one request per `POST /control`, or one message per text frame on a WebSocket \
             opened at `/control/ws`, which also carries notifications.\n",
            self.contract_version
        );
        let mut methods_by_group: BTreeMap<&str, Vec<&ControlContractEntryRead<'_>>> =
            BTreeMap::new();
        for method in &self.methods {
            methods_by_group
                .entry(method.group)
                .or_default()
                .push(method);
        }
        for (group, methods) in methods_by_group {
            let _ = write!(reference, "\n## {group}\n");
            for method in methods {
                let _ = write!(
                    reference,
                    "\n### `{}`\n\n{}\n\n{}\n\n- Since contract version {}, {}.\n- Params: `{}`\n- Result: `{}`\n- Errors: {}\n",
                    method.name,
                    method.summary,
                    method.description,
                    method.since_contract_version,
                    method.stability,
                    one_line(&typescript_type_of(method.params_schema, 0)),
                    one_line(&method.result_schema.map_or_else(
                        || "unknown".to_owned(),
                        |schema| typescript_type_of(schema, 0)
                    )),
                    method
                        .errors
                        .iter()
                        .map(|(code, message)| format!("`{code}` {message}"))
                        .collect::<Vec<_>>()
                        .join(", "),
                );
            }
        }
        if !self.notifications.is_empty() {
            reference.push_str("\n## Notifications\n");
            for notification in &self.notifications {
                let _ = write!(
                    reference,
                    "\n### `{}`\n\n{}\n\n- Sent after `{}`.\n- Since contract version {}, {}.\n- Params: `{}`\n",
                    notification.name,
                    notification.summary,
                    notification.subscribed_by,
                    notification.since_contract_version,
                    notification.stability,
                    one_line(&typescript_type_of(notification.params_schema, 0)),
                );
            }
        }
        reference
    }
}

impl<'contract> ControlContractEntryRead<'contract> {
    fn of(entry: &'contract Value) -> Result<Self> {
        let name = entry["name"]
            .as_str()
            .context("a contract entry has no `name`")?;
        Ok(Self {
            name,
            summary: entry["summary"].as_str().unwrap_or_default(),
            description: entry["description"].as_str().unwrap_or_default(),
            params_schema: &entry["params"][0]["schema"],
            result_schema: entry.get("result").map(|result| &result["schema"]),
            errors: entry["errors"]
                .as_array()
                .map(|errors| {
                    errors
                        .iter()
                        .filter_map(|error| {
                            Some((error["code"].as_i64()?, error["message"].as_str()?))
                        })
                        .collect()
                })
                .unwrap_or_default(),
            since_contract_version: entry["x-since"].as_u64().unwrap_or_default(),
            stability: entry["x-stability"].as_str().unwrap_or_default(),
            group: entry["x-group"].as_str().unwrap_or_default(),
            subscribed_by: entry["x-subscribed-by"].as_str().unwrap_or_default(),
        })
    }

    fn doc_paragraphs(&self) -> Vec<String> {
        let mut paragraphs = vec![self.summary.to_owned()];
        if !self.description.is_empty() && self.description != self.summary {
            paragraphs.push(self.description.to_owned());
        }
        paragraphs.push(format!(
            "Since contract version {}, {}.",
            self.since_contract_version, self.stability
        ));
        paragraphs
    }
}

fn description_of(schema: &Value) -> String {
    schema["description"]
        .as_str()
        .unwrap_or_default()
        .to_owned()
}

fn is_an_object_with_properties(schema: &Value) -> bool {
    schema.get("properties").is_some()
        && schema.get("oneOf").is_none()
        && schema.get("anyOf").is_none()
}

/// `schema` as a TypeScript type, nested objects indented from `indent_level`.
fn typescript_type_of(schema: &Value, indent_level: usize) -> String {
    match schema {
        Value::Bool(true) => return "unknown".to_owned(),
        Value::Bool(false) => return "never".to_owned(),
        _ => {}
    }
    if let Some(reference) = schema["$ref"].as_str() {
        return reference
            .strip_prefix(COMPONENT_SCHEMA_REFERENCE_PREFIX)
            .unwrap_or(reference)
            .to_owned();
    }
    if let Some(constant) = schema.get("const") {
        return json_literal(constant);
    }
    if let Some(variants) = schema["enum"].as_array() {
        return variants
            .iter()
            .map(json_literal)
            .collect::<Vec<_>>()
            .join(" | ");
    }
    for union_keyword in ["oneOf", "anyOf"] {
        if let Some(variants) = schema[union_keyword].as_array() {
            let union = variants
                .iter()
                .map(|variant| parenthesized(typescript_type_of(variant, indent_level)))
                .collect::<Vec<_>>()
                .join(" | ");
            return if schema.get("properties").is_some() {
                format!("{} & ({union})", object_type_of(schema, indent_level))
            } else {
                union
            };
        }
    }
    if let Some(parts) = schema["allOf"].as_array() {
        return parts
            .iter()
            .map(|part| parenthesized(typescript_type_of(part, indent_level)))
            .collect::<Vec<_>>()
            .join(" & ");
    }
    match &schema["type"] {
        Value::String(type_name) => typescript_type_of_a_json_type(type_name, schema, indent_level),
        Value::Array(type_names) => type_names
            .iter()
            .filter_map(Value::as_str)
            .map(|type_name| typescript_type_of_a_json_type(type_name, schema, indent_level))
            .collect::<Vec<_>>()
            .join(" | "),
        _ if schema.get("properties").is_some() => object_type_of(schema, indent_level),
        _ => "unknown".to_owned(),
    }
}

fn typescript_type_of_a_json_type(type_name: &str, schema: &Value, indent_level: usize) -> String {
    match type_name {
        "string" => "string".to_owned(),
        "integer" if is_a_wide_integer_format(schema) => "number | bigint".to_owned(),
        "integer" | "number" => "number".to_owned(),
        "boolean" => "boolean".to_owned(),
        "null" => "null".to_owned(),
        "array" => array_type_of(schema, indent_level),
        "object" => object_type_of(schema, indent_level),
        _ => "unknown".to_owned(),
    }
}

/// Whether an integer schema's format can hold a value past `Number.MAX_SAFE_INTEGER`, which the
/// client reads as a `bigint`.
pub(crate) fn is_a_wide_integer_format(schema: &Value) -> bool {
    matches!(schema["format"].as_str(), Some("uint64" | "int64"))
}

fn array_type_of(schema: &Value, indent_level: usize) -> String {
    let item_type = schema.get("items").map_or_else(
        || "unknown".to_owned(),
        |items| typescript_type_of(items, indent_level),
    );
    match (schema["minItems"].as_u64(), schema["maxItems"].as_u64()) {
        (Some(min_items), Some(max_items)) if min_items == max_items && max_items <= 8 => {
            let tuple_items = vec![item_type; usize::try_from(max_items).unwrap_or_default()];
            format!("[{}]", tuple_items.join(", "))
        }
        _ => format!("Array<{item_type}>"),
    }
}

fn object_type_of(schema: &Value, indent_level: usize) -> String {
    let properties = schema["properties"].as_object();
    let required: Vec<&str> = schema["required"]
        .as_array()
        .map(|required| required.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    let additional_properties = schema.get("additionalProperties");
    let property_count = properties.map_or(0, Map::len);
    if property_count == 0 {
        return match additional_properties {
            Some(Value::Bool(false)) => "Record<string, never>".to_owned(),
            Some(Value::Bool(true)) | None => "{ [key: string]: unknown }".to_owned(),
            Some(value_schema) => {
                format!(
                    "{{ [key: string]: {} }}",
                    typescript_type_of(value_schema, indent_level)
                )
            }
        };
    }
    let member_indent = "  ".repeat(indent_level + 1);
    let mut object_type = String::from("{\n");
    for (property_name, property_schema) in properties.into_iter().flatten() {
        write_doc_comment(
            &mut object_type,
            &member_indent,
            &[description_of(property_schema)],
        );
        let optional_marker = if required.contains(&property_name.as_str()) {
            ""
        } else {
            "?"
        };
        let _ = writeln!(
            object_type,
            "{member_indent}{}{optional_marker}: {};",
            property_key(property_name),
            typescript_type_of(property_schema, indent_level + 1)
        );
    }
    if let Some(value_schema) =
        additional_properties.filter(|value| !matches!(value, Value::Bool(false)))
    {
        let _ = writeln!(
            object_type,
            "{member_indent}[key: string]: {};",
            match value_schema {
                Value::Bool(true) => "unknown".to_owned(),
                value_schema => typescript_type_of(value_schema, indent_level + 1),
            }
        );
    }
    let _ = write!(object_type, "{}}}", "  ".repeat(indent_level));
    object_type
}

fn write_doc_comment(written: &mut String, indent: &str, paragraphs: &[String]) {
    let paragraphs: Vec<&String> = paragraphs
        .iter()
        .filter(|paragraph| !paragraph.is_empty())
        .collect();
    if paragraphs.is_empty() {
        return;
    }
    let _ = writeln!(written, "{indent}/**");
    for (index, paragraph) in paragraphs.iter().enumerate() {
        if index > 0 {
            let _ = writeln!(written, "{indent} *");
        }
        for line in paragraph.replace("*/", "*\\/").lines() {
            let _ = writeln!(written, "{indent} * {line}");
        }
    }
    let _ = writeln!(written, "{indent} */");
}

pub(crate) fn property_key(name: &str) -> String {
    let is_an_identifier = name
        .chars()
        .next()
        .is_some_and(|first| first.is_ascii_alphabetic() || first == '_' || first == '$')
        && name.chars().all(|character| {
            character.is_ascii_alphanumeric() || character == '_' || character == '$'
        });
    if is_an_identifier {
        name.to_owned()
    } else {
        json_string_literal(name)
    }
}

fn parenthesized(typescript_type: String) -> String {
    if typescript_type.contains(" | ") || typescript_type.contains(" & ") {
        format!("({typescript_type})")
    } else {
        typescript_type
    }
}

fn one_line(typescript_type: &str) -> String {
    typescript_type
        .lines()
        .map(str::trim)
        .filter(|line| !line.starts_with("/**") && !line.starts_with('*'))
        .collect::<Vec<_>>()
        .join(" ")
}

fn json_literal(value: &Value) -> String {
    serde_json::to_string(value).unwrap_or_else(|_| unreachable!("a JSON value always serializes"))
}

fn json_string_literal(text: &str) -> String {
    json_literal(&Value::String(text.to_owned()))
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn a_schema_object_becomes_an_interface_with_its_optional_and_nullable_fields() {
        let schema = json!({
            "type": "object",
            "properties": {
                "stream": { "type": "string", "format": "uuid", "description": "The stream." },
                "name": { "type": ["string", "null"] },
                "pins": { "type": ["object", "null"], "additionalProperties": true }
            },
            "required": ["stream"],
            "additionalProperties": false
        });
        assert_eq!(
            object_type_of(&schema, 0),
            "{\n  /**\n   * The stream.\n   */\n  stream: string;\n  name?: string | null;\n  pins?: { [key: string]: unknown } | null;\n}"
        );
    }

    #[test]
    fn a_tagged_union_a_reference_and_a_fixed_length_array_keep_their_shape() {
        assert_eq!(
            typescript_type_of(
                &json!({ "oneOf": [
                    { "type": "object", "properties": { "operation": { "const": "add_node", "type": "string" } }, "required": ["operation"] },
                    { "$ref": "#/components/schemas/StreamGraphActionLinkEnd" }
                ] }),
                0
            ),
            "{\n  operation: \"add_node\";\n} | StreamGraphActionLinkEnd"
        );
        assert_eq!(
            typescript_type_of(
                &json!({ "type": "array", "items": { "type": "number" }, "minItems": 2, "maxItems": 2 }),
                0
            ),
            "[number, number]"
        );
        assert_eq!(
            typescript_type_of(
                &json!({ "type": "object", "additionalProperties": false }),
                0
            ),
            "Record<string, never>"
        );
    }

    #[test]
    fn the_committed_contract_file_generates_every_method_and_notification() {
        let contract_file_contents =
            include_str!("../../runtime/streamlib-control-contract/contract.json");
        let contract: Value = serde_json::from_str(contract_file_contents).unwrap();
        let generated_files =
            runtime_client_generated_files(&contract, contract_file_contents).unwrap();
        let declarations = &generated_files[0].1;
        for method in contract["methods"].as_array().unwrap() {
            let method_name = method["name"].as_str().unwrap();
            assert!(
                declarations.contains(&format!("  {method_name}: {{\n")),
                "{method_name}"
            );
        }
        assert!(declarations.contains("  project_changed: ProjectChangedNotificationParams;"));
    }

    #[test]
    fn the_client_has_one_method_per_operation_and_one_listener_per_notification() {
        let contract_file_contents =
            include_str!("../../runtime/streamlib-control-contract/contract.json");
        let contract: Value = serde_json::from_str(contract_file_contents).unwrap();
        let generated_files =
            runtime_client_generated_files(&contract, contract_file_contents).unwrap();
        let client_source = &generated_files
            .iter()
            .find(|(file_name, _)| *file_name == GENERATED_CLIENT_FILE_NAME)
            .unwrap()
            .1;
        assert!(client_source.contains(
            "  open_project(params, callOptions) {\n    return this.call(\"open_project\", params, callOptions);\n  }"
        ));
        assert!(client_source.contains("  describe_runtime(params = {}, callOptions) {"));
        assert!(client_source.contains(
            "  on_project_changed(listener) {\n    return this.onNotification(\"project_changed\", listener);\n  }"
        ));
    }

    #[test]
    fn an_operation_named_like_a_member_of_the_client_is_refused() {
        let contract = json!({
            "info": { "x-contract-version": 1 },
            "components": { "schemas": {} },
            "methods": [{ "name": "close", "params": [{ "schema": {} }] }],
            "x-notifications": []
        });
        let refusal = runtime_client_generated_files(&contract, "")
            .err()
            .unwrap()
            .to_string();
        assert!(
            refusal.contains("`close` is the name of a member"),
            "{refusal}"
        );
    }
}
